// ─── Branded IDs ────────────────────────────────────────────────────────────
export type BundleId = string & { __brand: "BundleId" };
export type BundleItemId = string & { __brand: "BundleItemId" };
export type BundleTierId = string & { __brand: "BundleTierId" };
export type BundlePurchaseRecordId = string & { __brand: "BundlePurchaseRecordId" };
export type BundleHealthEventId = string & { __brand: "BundleHealthEventId" };

// Shopify external IDs stored as BIGINT in DB, compared as strings in JS maps
export type VariantExternalId = string & { __brand: "VariantExternalId" };
export type ProductExternalId = string & { __brand: "ProductExternalId" };
export type OrderExternalId = string & { __brand: "OrderExternalId" };

// ─── Enumerations ────────────────────────────────────────────────────────────
export type BundleMode = "fixed" | "flexible";
export type BundleHealthStatus = "healthy" | "warned" | "auto_disabled";
export type ObservedAvailability = "available" | "out_of_stock" | "deleted";
export type HealthEventKind = "auto_disabled" | "warned" | "cleared";

// ─── DB Row Types ─────────────────────────────────────────────────────────────
export interface BundleRow {
  id: BundleId;
  title: string;
  description: string | null;
  mode: BundleMode;
  enabled: boolean;
  health_status: BundleHealthStatus;
  created_at: Date;
  updated_at: Date;
}

export interface BundleItemRow {
  id: BundleItemId;
  bundle_id: BundleId;
  variant_external_id: string; // BIGINT comes back as string from postgres.js
  product_external_id: string;
  observed_availability: ObservedAvailability;
  added_at: Date;
}

export interface BundleTierRow {
  id: BundleTierId;
  bundle_id: BundleId;
  minimum_item_count: number;
  discount_rate: number; // basis points, e.g. 1000 = 10%
  display_order: number;
  created_at: Date;
  updated_at: Date;
}

export interface BundlePurchaseRecordRow {
  id: BundlePurchaseRecordId;
  bundle_id: BundleId;
  order_external_id: string; // BIGINT
  order_placed_at: Date;
  variant_external_ids: string; // JSON-serialized string[]
  item_count: number;
  discount_rate_applied: number; // basis points
  order_total: string; // BIGINT — minor currency units
  order_currency: string;
  recorded_at: Date;
}

export interface BundleHealthEventRow {
  id: BundleHealthEventId;
  bundle_id: BundleId;
  event_kind: HealthEventKind;
  affected_variant_external_id: string | null; // BIGINT nullable
  reason: string;
  occurred_at: Date;
}

// ─── HTTP Request/Response: Admin Routes ─────────────────────────────────────

// GET /admin/bundles
export interface AdminListBundlesRequest {
  status_filter?: "enabled" | "disabled" | "all";
  health_filter?: BundleHealthStatus | "all";
  cursor?: string;
  page_size?: number;
}

export interface AdminBundleSummary {
  id: BundleId;
  title: string;
  description: string | null;
  mode: BundleMode;
  enabled: boolean;
  health_status: BundleHealthStatus;
  tier_count: number;
  item_count: number;
  created_at: string;
  updated_at: string;
}

export interface AdminListBundlesResponse {
  bundles: AdminBundleSummary[];
  next_cursor: string | null;
  total_count: number;
}

// POST /admin/bundles/create
export interface AdminCreateBundleRequest {
  title: string;
  mode: BundleMode;
  description?: string;
}

export interface AdminCreateBundleResponse {
  bundle_id: BundleId;
  status: "created";
}

// PUT /admin/bundles/update
export interface AdminUpdateBundleRequest {
  bundle_id: BundleId;
  title?: string;
  description?: string | null;
  mode?: BundleMode;
  enabled?: boolean;
}

export interface AdminUpdateBundleResponse {
  bundle_id: BundleId;
  updated_at: string;
}

// POST /admin/bundles/remove
export interface AdminRemoveBundleRequest {
  bundle_id: BundleId;
}

export interface AdminRemoveBundleResponse {
  success: boolean;
}

// POST /admin/bundles/clone
export interface AdminCloneBundleRequest {
  source_bundle_id: BundleId;
}

export interface AdminCloneBundleResponse {
  new_bundle_id: BundleId;
  status: "created";
}

// POST /admin/bundles/bulk-status
export interface AdminBulkStatusRequest {
  bundle_ids: BundleId[];
  enabled: boolean;
}

export interface AdminBulkStatusResponse {
  updated_count: number;
  skipped_count: number;
}

// GET /admin/bundles/items
export interface AdminListItemsRequest {
  bundle_id: BundleId;
  cursor?: string;
  page_size?: number;
}

export interface AdminBundleItemSummary {
  id: BundleItemId;
  bundle_id: BundleId;
  variant_external_id: string;
  product_external_id: string;
  observed_availability: ObservedAvailability;
  added_at: string;
}

export interface AdminListItemsResponse {
  items: AdminBundleItemSummary[];
  next_cursor: string | null;
  total_count: number;
}

// POST /admin/bundles/items/save
export interface AdminSaveItemsRequest {
  bundle_id: BundleId;
  variant_external_ids: string[];
  product_external_ids: string[];
}

export interface AdminSaveItemsResponse {
  saved_count: number;
  unavailable_variants: string[];
}

// GET /admin/bundles/tiers
export interface AdminListTiersRequest {
  bundle_id: BundleId;
  cursor?: string;
}

export interface AdminTierSummary {
  id: BundleTierId;
  bundle_id: BundleId;
  minimum_item_count: number;
  discount_rate: number;
  display_order: number;
}

export interface AdminListTiersResponse {
  tiers: AdminTierSummary[];
  next_cursor: string | null;
  total_count: number;
}

// POST /admin/bundles/tiers/save
export interface TierInput {
  minimum_item_count: number;
  discount_rate: number; // basis points
}

export interface AdminSaveTiersRequest {
  bundle_id: BundleId;
  tiers: TierInput[];
}

export interface AdminSaveTiersResponse {
  saved_count: number;
}

// GET /admin/purchase-history
export interface AdminPurchaseHistoryRequest {
  bundle_id?: BundleId;
  date_from?: string;
  date_to?: string;
  cursor?: string;
  page_size?: number;
}

export interface PurchaseRecordSummary {
  id: BundlePurchaseRecordId;
  bundle_id: BundleId;
  order_external_id: string;
  order_placed_at: string;
  variant_external_ids: string[];
  item_count: number;
  discount_rate_applied: number;
  order_total: string;
  order_currency: string;
  recorded_at: string;
}

export interface AdminPurchaseHistoryResponse {
  records: PurchaseRecordSummary[];
  next_cursor: string | null;
  total_count: number;
}

// ─── HTTP Request/Response: Widget Routes ────────────────────────────────────

// GET /widget/bundle
export interface WidgetBundleRequest {
  bundle_id: BundleId;
  cursor?: string;
}

export interface WidgetTier {
  id: BundleTierId;
  minimum_item_count: number;
  discount_rate: number; // basis points
  display_order: number;
}

export interface WidgetItem {
  id: BundleItemId;
  variant_external_id: string;
  product_external_id: string;
  observed_availability: ObservedAvailability;
}

export interface WidgetBundleConfig {
  id: BundleId;
  title: string;
  description: string | null;
  mode: BundleMode;
  enabled: boolean;
  health_status: BundleHealthStatus;
}

export interface WidgetBundleResponse {
  bundle: WidgetBundleConfig;
  tiers: WidgetTier[];
  items: WidgetItem[];
  next_cursor: string | null;
  total_count: number;
}

// POST /widget/bundle/validate
export interface WidgetValidateRequest {
  bundle_id: BundleId;
  selected_variant_ids: string[];
}

export interface WidgetEarnedTier {
  id: BundleTierId;
  minimum_item_count: number;
  discount_rate: number;
}

export interface WidgetValidateResponse {
  valid: boolean;
  earned_tier: WidgetEarnedTier | null;
  discount_rate: number; // basis points, 0 if no tier reached
  validation_errors: string[];
}

// POST /widget/cart/add
export interface WidgetCartAddRequest {
  bundle_id: BundleId;
  selected_variant_ids: string[];
  quantities: number[];
}

export interface WidgetCartAddResponse {
  success: boolean;
  cart_external_id: string | null;
  applied_discount_rate: number; // basis points
  errors: string[];
}

// ─── Webhook Payload Types ───────────────────────────────────────────────────

export interface OrderLineItem {
  variant_id: number | null;
  product_id: number | null;
  quantity: number;
  price: string;
  properties: Array<{ name: string; value: string }>;
}

export interface OrderDiscountCode {
  code: string;
  amount: string;
  type: string;
}

export interface OrdersPaidPayload {
  id: number;
  created_at: string;
  currency: string;
  total_price: string;
  line_items: OrderLineItem[];
  discount_codes: OrderDiscountCode[];
}

export interface VariantStockPayload {
  id: number;           // variant id
  product_id: number;
  inventory_quantity: number;
}

export interface ProductsDeletePayload {
  id: number; // product id
}

// ─── Internal computation types ──────────────────────────────────────────────

export interface BundleHealthEvalResult {
  bundle_id: BundleId;
  new_health_status: BundleHealthStatus;
  should_disable: boolean;
  event_kind: HealthEventKind;
  reason: string;
}
